const getOverworldObjects = (teamState: TeamHuntState): OverworldObject[] => {
  const objects: OverworldObject[] = [];
  for (const zone of ZONE_DEFINITIONS) {
    const round = teamState.rounds[zone.slug];
    const lockState = round?.locked ?? "locked";
    if (lockState === "locked") {
      continue;
    }
    const zoneX = ZONE_BASE_POSITION.x + zone.offsetX;
    const zoneY = ZONE_BASE_POSITION.y + zone.offsetY;
    const boundaryAsset = zone.boundaryAsset;
    const base = {
      slug: zone.slug,
      name: zone.name,
      x: zoneX,
      y: zoneY,
      type: zone.type,
      tooltip_position: zone.tooltipPosition,
      z_index: zone.zIndex,
      boundary_asset: boundaryAsset,
    } satisfies Omit<OverworldObject, "asset">;

    if (lockState === "unlocked") {
      objects.push({
        ...base,
        asset: zone.unlockedAsset,
        href: `/rounds/${zone.slug}`,
      });
      continue;
    }

    if (lockState !== "unlockable") {
      continue;
    }

    const cost = round?.unlock_cost ?? 1;
    objects.push({
      ...base,
      asset: zone.unlockableAsset,
      round_unlock: {
        slug: zone.slug,
        title: round?.title ?? zone.name,
        desc: round?.desc,
        cost,
      },
    });
  }

  for (const dimension of DIMENSIONS) {
    const round = teamState.rounds[dimension.slug];
    const lockState = round?.locked ?? "locked";
    const isSolved =
      IS_STATIC_SITE ||
      (lockState === "unlocked" &&
        !!teamState.puzzles[dimension.metaSlug]?.solved);
    const dimensionX = dimension.offsetX + DIMENSION_BASE_POSITION.x;
    const dimensionY = dimension.offsetY + DIMENSION_BASE_POSITION.y;
    const base = {
      slug: dimension.slug,
      name: dimension.name,
      x: dimensionX,
      y: dimensionY,
      type: dimension.type,
      tooltip_position: dimension.tooltipPosition,
      z_index: dimension.zIndex,
      boundary_asset: dimension.boundaryAsset,
    } satisfies Omit<OverworldObject, "asset">;

    if (isSolved) {
      objects.push({
        ...base,
        name: base.name + " ✔️",
        asset: dimension.solvedAsset,
        href: `/rounds/${dimension.slug}`,
      });
    } else {
      if (lockState === "unlocked") {
        objects.push({
          ...base,
          asset: dimension.unlockedAsset,
          href: `/rounds/${dimension.slug}`,
        });
      }

      if (lockState === "unlockable") {
        const cost = round?.unlock_cost ?? 1;
        objects.push({
          ...base,
          asset: dimension.unlockableAsset,
          round_unlock: {
            slug: dimension.slug,
            title: round?.title ?? dimension.name,
            desc: round?.desc,
            cost,
          },
        });
      }
    }
  }

  const capstone = teamState.puzzles[FRIENDSHIP_METAMETA.slug];
  const capstoneLockState = capstone?.locked ?? "locked";
  const capstoneBase = {
    slug: FRIENDSHIP_METAMETA.slug,
    name: FRIENDSHIP_METAMETA.label,
    x: FRIENDSHIP_METAMETA.offsetX,
    y: FRIENDSHIP_METAMETA.offsetY,
    tooltip_position: FRIENDSHIP_METAMETA.tooltipPosition,
    z_index: FRIENDSHIP_METAMETA.zIndex,
    type: FRIENDSHIP_METAMETA.type,
    boundary_asset: FRIENDSHIP_METAMETA.boundaryAsset,
  };

  if (capstoneLockState === "unlocked") {
    objects.push({
      ...capstoneBase,
      asset: FRIENDSHIP_METAMETA.unlockedAsset,
      href: `/puzzles/${FRIENDSHIP_METAMETA.slug}`,
    });
  } else if (capstoneLockState === "unlockable") {
    objects.push({
      ...capstoneBase,
      asset: FRIENDSHIP_METAMETA.lockedAsset,
      puzzle_unlock: {
        slug: FRIENDSHIP_METAMETA.slug,
        title: FRIENDSHIP_METAMETA.label,
        desc: FRIENDSHIP_METAMETA.label,
        cost: capstone.unlock_cost ?? 1,
        physical_presence_requirement: "recommended_with_pickup",
      },
    });
  }

  const kingdomRunaround = teamState.puzzles[MIDPOINT_RUNAROUND.slug];
  const kingdomRunaroundLockState = kingdomRunaround?.locked ?? "locked";
  if (kingdomRunaroundLockState === "unlocked") {
    objects.push({
      slug: MIDPOINT_RUNAROUND.slug,
      name: MIDPOINT_RUNAROUND.label,
      x: MIDPOINT_RUNAROUND.offsetX,
      y: MIDPOINT_RUNAROUND.offsetY,
      type: MIDPOINT_RUNAROUND.type,
      tooltip_position: MIDPOINT_RUNAROUND.tooltipPosition,
      boundary_asset: MIDPOINT_RUNAROUND.boundaryAsset,
      asset: MIDPOINT_RUNAROUND.unlockedAsset,
      href: `/puzzles/${MIDPOINT_RUNAROUND.slug}`,
    });
  }

  for (const meta of RESEARCH_META_DEFINITIONS) {
    const puzzle = teamState.puzzles[meta.slug];
    if (!puzzle) {
      continue;
    }

    const solveState = puzzle.solved ?? undefined;
    const lockState = puzzle.locked ?? "locked";
    if (lockState === "locked") {
      continue;
    }

    const metaX = RESEARCH_META_BASE_POSITION.x + meta.offsetX;
    const metaY = RESEARCH_META_BASE_POSITION.y + meta.offsetY;
    const base: Omit<OverworldObject, "asset"> = {
      slug: meta.slug,
      name: meta.label,
      x: metaX,
      y: metaY,
      type: meta.type,
      tooltip_position: meta.tooltipPosition,
      z_index: meta.zIndex,
      boundary_asset: meta.boundaryAsset,
    };

    if (solveState && meta.solvedAsset) {
      objects.push({
        ...base,
        asset: meta.solvedAsset,
        href: `/puzzles/${meta.slug}`,
      });
      continue;
    } else if (lockState === "unlocked") {
      objects.push({
        ...base,
        asset: meta.unlockedAsset,
        href: `/puzzles/${meta.slug}`,
      });
      continue;
    }

    const cost = puzzle.unlock_cost ?? 1;
    objects.push({
      ...base,
      asset: meta.lockedAsset,
      puzzle_unlock: {
        slug: meta.slug,
        title: meta.label,
        cost,
        is_overworld_feeder: puzzle.is_overworld_feeder,
      },
    });
  }

  return objects;
};

export function toHubState(teamState: TeamHuntState): HubState {
  const rounds = Object.entries(teamState.rounds).map(([slug, roundObj]) => {
    return {
      slug,
      title: roundObj.title,
      locked: roundObj.locked,
      unlock_cost: roundObj.unlock_cost,
    };
  });

  return {
    epoch: teamState.epoch,
    rounds,
    overworld_objects: getOverworldObjects(teamState),
    hunt_has_started: HUNT_STARTED(teamState),
    currency: teamState.currency,
  };
}
